import React from "react";
import { Check as CheckIcon } from "@exp-textura/icons";
import { Menu } from "@components/menu";

import { useTabBar } from "../hooks/use-tab-bar";

import { Tab } from "./tab";

export const OverflowMenu: React.FC<{
  allTriggers: React.ReactElement[];
  overflowValues: string[];
  moreButtonRef: React.RefObject<HTMLDivElement>;
  overflowMenuTriggerLabel?: React.ReactNode;
}> = ({ allTriggers, overflowValues, moreButtonRef, overflowMenuTriggerLabel = "More" }) => {
  const { activeTab, setActiveTab } = useTabBar();

  return (
    <Menu>
      <Menu.Trigger>
        <Tab ref={moreButtonRef}>
          {overflowMenuTriggerLabel}
          <Tab.ActionButton action="menu" />
        </Tab>
      </Menu.Trigger>
      <Menu.Content>
        {allTriggers
          .filter((child) => overflowValues.includes(child.props.value))
          .map((child) => {
            const value = child.props.value;
            const isActive = value === activeTab;

            return (
              <Menu.Item key={value} onSelect={() => setActiveTab(value)}>
                <span style={{ display: "flex", justifyContent: "space-between", width: "100%" }}>
                  {child.props.children}
                  {isActive && <CheckIcon />}
                </span>
              </Menu.Item>
            );
          })}
      </Menu.Content>
    </Menu>
  );
};
